 const mapWindow=fp.querySelector('#fantasy-settlementMapWindow'), grid=fp.querySelector('#fantasy-settlementMapGridOverlay');fp.querySelector('#fantasy-mapGridToggle')?.addEventListener('click',e=>{grid?.classList.toggle('hidden');e.currentTarget.setAttribute('aria-pressed',String(!grid?.classList.contains('hidden')))});fp.querySelector('#fantasy-mapFitToggle')?.addEventListener('click',e=>{mapWindow?.classList.toggle('fill');e.currentTarget.setAttribute('aria-pressed',String(mapWindow?.classList.contains('fill')))});fp.querySelector('#fantasy-mapResetButton')?.addEventListener('click',()=>mapWindow?.classList.remove('fill'));fp.querySelector('#fantasy-mapFullscreenButton')?.addEventListener('click',()=>mapWindow?.requestFullscreen?.());filterTravel();
